def measures_none(apps, schema_editor):
    """A class with a single price had no size variant measure; it is now "none"."""
    apps.get_model("vehicles", "VehicleClass").objects.filter(size_variant_measures="").update(size_variant_measures="none")


def hand_set_classes_to_overrides(apps, schema_editor):
    """A class set by hand on a vehicle model becomes a model override, so
    classify_vehicles keeps it."""
    VehicleModel = apps.get_model("vehicles", "VehicleModel")
    ModelOverride = apps.get_model("vehicles", "ModelOverride")
    for vehicle_model in VehicleModel.objects.filter(vehicle_class__isnull=False):
        ModelOverride.objects.create(
            vehicle_model=vehicle_model,
            vehicle_class_id=vehicle_model.vehicle_class_id,
            size_variant_id=vehicle_model.size_variant_id,
            ask_size=vehicle_model.ask_size,
            note="Set by hand on the vehicle model before Phase 2 Step 2.",
        )


